/**
 * Content-addressed media store.
 *
 * Generated bytes are the one thing this application cannot put in SQLite and the
 * one thing it must never route through IPC as a JSON string. Files live under the
 * profile's media directory named by their own SHA-256, so:
 *
 *  - the same image generated twice occupies one file;
 *  - a row's `sha256` can be verified against the file at any time;
 *  - a path can never be chosen by a provider, a prompt or the renderer.
 *
 * Every path that enters this module is validated against the media root before a
 * file handle is opened, and only a content-addressed name is accepted, so a
 * `../../` or an absolute path is refused rather than resolved.
 *
 * Writes are atomic (temp file in the same directory, then rename), and the file
 * mode is owner-only: these are the user's images, not shared artefacts.
 */
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { MEDIA_LIMITS, extensionForMime, type MediaKind } from '@shared/media';

/** `ab/abcdef…f.png` — two hex digits, the full digest, an extension we chose. */
const RELATIVE_PATH_PATTERN = /^[0-9a-f]{2}\/[0-9a-f]{64}\.[a-z0-9]{1,8}$/;

export class MediaPathError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MediaPathError';
  }
}

export interface StoredMedia {
  relativePath: string;
  sha256: string;
  bytes: number;
  mime: string;
}

export interface MediaStoreOptions {
  /** Absolute path of the media root. Created on demand. */
  rootDir: string;
  /** Per-file ceiling; defaults to the documented limit. */
  maxFileBytes?: number;
}

export class MediaStore {
  readonly rootDir: string;
  private readonly maxFileBytes: number;

  constructor(options: MediaStoreOptions) {
    this.rootDir = path.resolve(options.rootDir);
    this.maxFileBytes = options.maxFileBytes ?? MEDIA_LIMITS.maxFileBytes;
    fs.mkdirSync(this.rootDir, { recursive: true });
  }

  /** Absolute path for a validated relative path. Throws rather than escaping the root. */
  resolve(relativePath: string): string {
    if (!RELATIVE_PATH_PATTERN.test(relativePath)) {
      throw new MediaPathError('That is not a media path this app wrote.');
    }
    const absolute = path.resolve(this.rootDir, relativePath);
    const root = this.rootDir.endsWith(path.sep) ? this.rootDir : `${this.rootDir}${path.sep}`;
    if (!absolute.startsWith(root)) {
      throw new MediaPathError('That path is outside the media directory.');
    }
    return absolute;
  }

  /**
   * Writes bytes and returns their identity.
   *
   * Idempotent: writing the same bytes again returns the same relative path and
   * leaves the existing file untouched.
   */
  save(bytes: Uint8Array, mime: string, _kind: MediaKind): StoredMedia {
    if (bytes.byteLength === 0) throw new MediaPathError('Refusing to store an empty file.');
    if (bytes.byteLength > this.maxFileBytes) {
      throw new MediaPathError(
        `That file is larger than the ${Math.round(this.maxFileBytes / (1024 * 1024))} MB this app will store.`,
      );
    }

    const sha256 = createHash('sha256').update(bytes).digest('hex');
    const relativePath = `${sha256.slice(0, 2)}/${sha256}.${extensionForMime(mime)}`;
    const target = this.resolve(relativePath);

    if (fs.existsSync(target)) {
      return { relativePath, sha256, bytes: bytes.byteLength, mime };
    }

    fs.mkdirSync(path.dirname(target), { recursive: true });
    const temp = `${target}.${process.pid}.tmp`;
    try {
      fs.writeFileSync(temp, bytes, { mode: 0o600 });
      fs.renameSync(temp, target);
    } catch (error) {
      // A failed write must not leave a temp file behind for the next run to trip on.
      fs.rmSync(temp, { force: true });
      throw error;
    }

    return { relativePath, sha256, bytes: bytes.byteLength, mime };
  }

  /** Reads a stored file. Throws for a path this store did not write. */
  read(relativePath: string): Buffer {
    return fs.readFileSync(this.resolve(relativePath));
  }

  exists(relativePath: string): boolean {
    return fs.existsSync(this.resolve(relativePath));
  }

  /** Size of a stored file, or null when it is gone. */
  size(relativePath: string): number | null {
    try {
      return fs.statSync(this.resolve(relativePath)).size;
    } catch {
      return null;
    }
  }

  /**
   * Deletes exactly one stored file.
   *
   * Returns false when it was already absent: a missing file is not an error, but
   * it is never silently treated as a successful delete of something else.
   */
  remove(relativePath: string): boolean {
    const target = this.resolve(relativePath);
    try {
      fs.rmSync(target, { force: false });
      return true;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false;
      throw error;
    }
  }

  /** Bytes currently on disk under the root, for the storage budget. */
  totalBytes(): number {
    let total = 0;
    const walk = (dir: string): void => {
      let entries: fs.Dirent[];
      try {
        entries = fs.readdirSync(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full);
        else if (entry.isFile()) {
          try {
            total += fs.statSync(full).size;
          } catch {
            /* a file removed between readdir and stat is simply not counted */
          }
        }
      }
    };
    walk(this.rootDir);
    return total;
  }
}
